import { RestClientBase } from "../Common/RestClientBase";
export class ResourceUsageRestClient extends RestClientBase {
    constructor(options) {
        super(options);
    }
    /**
     * Gets the Project Level limits and Usage for a project.
     *
     * @param project - Project ID or project name
     */
    async getProjectLimit(project) {
        return this.beginRequest({
            apiVersion: "7.1-preview.1",
            routeTemplate: "{project}/_apis/ResourceUsage",
            routeValues: {
                project: project
            }
        });
    }
    /**
     */
    async getLimits() {
        return this.beginRequest({
            apiVersion: "7.1-preview.1",
            routeTemplate: "_apis/ResourceUsage"
        });
    }
}
ResourceUsageRestClient.RESOURCE_AREA_ID = "240a9b11-3dc7-4aa0-b3fe-2b7dc8a4e7ea";
